16	export function createMcpClient(restClient: NextRESTClient): McpClient {
17	  // One connected client per API key — the handshake runs once, then reused.
18	  const clients = new Map<string, Promise<Client>>()
19	
20	  return {
21	    close: async () => {
22	      const pending = [...clients.values()]
23	      clients.clear()
24	      await Promise.all(
25	        pending.map(async (client) => {
26	          try {
27	            await (await client).close()
28	          } catch {
29	            // Best-effort teardown — a failed handshake leaves nothing to close.
30	          }
31	        }),
32	      )
33	    },
34	    connect: (apiKey) => {
35	      let client = clients.get(apiKey)
36	      if (!client) {
37	        client = connectMcpClient({ apiKey, restClient })
38	        clients.set(apiKey, client)
39	      }
40	      return client
41	    },
42	    rawPost: async ({ apiKey, body }) =>
43	      restClient.POST('/mcp', {
44	        body: JSON.stringify(body),
45	        headers: {
46	          Accept: 'application/json, text/event-stream',
47	          ...(apiKey ? { Authorization: `users API-Key ${apiKey}` } : {}),
48	          'Content-Type': 'application/json',
49	        },
50	      }),
51	  }
52	}
