import { defaultAccess } from '../../../defaultAccess.js'
import { defineCollectionTool } from '../../../defineTool.js'
import { getLogger } from '../../../utils/getLogger.js'
import { localAPIDefaults } from '../../../utils/localAPIDefaults.js'
import { whereSchema } from '../../../utils/whereSchema.js'

const DEFAULT_DESCRIPTION =
  'Count documents in any collection by passing the collection slug and an optional where clause.'

export const countDocumentsTool = defineCollectionTool({
  access: (args) =>
    defaultAccess(args) && Boolean(args.permissions?.collections?.[args.collectionSlug]?.read),
  annotations: {
    destructiveHint: false,
    idempotentHint: true,
    openWorldHint: false,
    readOnlyHint: true,
    title: 'Count Documents',
  },
  description: DEFAULT_DESCRIPTION,
  input: z.object({
    locale: z
      .string()
      .describe('Optional: locale code to count documents in (e.g., "en", "es")')
      .optional(),
    where: whereSchema
      .describe(
        'Optional: where clause for filtering. Use field names with Payload operators, and/or arrays for grouping. Example: {"title":{"contains":"test"}}',
      )
      .optional(),
  }),
}).handler(async ({ authorizedMCP, collectionSlug, input, req }) => {
  const payload = req.payload
  const logger = getLogger({ payload })

  const { locale, where } = input

  logger.info(
    `Counting documents in collection: ${collectionSlug}${locale ? `, locale: ${locale}` : ''}`,
  )

  try {
    const countOptions: Parameters<typeof payload.count>[0] = {
      collection: collectionSlug,
      req,
      ...localAPIDefaults(authorizedMCP),
      ...(locale && { locale }),
    }

    if (where) {
      countOptions.where = where
    }

    const result = await payload.count(countOptions)

    return {
      content: [
        {
          type: 'text',
          text: `Collection "${collectionSlug}" contains ${result.totalDocs} documents.\n\`\`\`json\n${JSON.stringify(result)}\n\`\`\``,
        },
      ],
      structuredContent: { totalDocs: result.totalDocs },
    }
  } catch (error) {
    const errorMessage = error instanceof Error ? error.message : 'Unknown error'
    logger.error(`Error counting documents in collection ${collectionSlug}: ${errorMessage}`)
    return {
      content: [
        {
          type: 'text',
          text: `❌ **Error counting documents in collection "${collectionSlug}":** ${errorMessage}`,
        },
      ],
      isError: true,
    }
  }
})
