    readOnlyHint: false,
    title: 'Duplicate Document',
  },
  description: DEFAULT_DESCRIPTION,
  input: z.object({
    id: z
      .union([z.string(), z.number()])
      .describe('The ID of the source document to duplicate'),
    data: z
      .record(z.string(), z.unknown())
      .describe('Optional: fields to override on the duplicated document')
      .optional(),
    depth: z
      .number()
      .int()
      .min(0)
      .max(10)
      .describe('How many levels deep to populate relationships in response')
      .optional()
      .default(0),
    draft: z
      .boolean()
      .describe('Optional: whether to create the duplicate as a draft')
      .optional(),
    fallbackLocale: z
      .string()
      .describe('Optional: fallback locale code to use when requested locale is not available')
      .optional(),
    locale: z
      .string()
      .describe('Optional: locale code to duplicate the document in (e.g., "en", "es")')
      .optional(),
    select: z
      .record(z.string(), z.unknown())
      .describe(
        'Optional: define exactly which fields you\'d like to return, e.g., {"title": true}',
      )
      .optional(),
  }),
}).handler(async ({ authorizedMCP, collectionSlug, input, req }) => {
  const payload = req.payload
  const logger = getLogger({ payload })

  const { id, data, depth, draft, fallbackLocale, locale, select } = input

  logger.info(
    `Duplicating document with ID: ${id} in collection: ${collectionSlug}${locale ? ` with locale: ${locale}` : ''}`,
  )

  try {
    const duplicateOptions: Parameters<typeof payload.duplicate>[0] = {
      id,
      collection: collectionSlug,
      depth,
      req,
      ...localAPIDefaults(authorizedMCP),
      ...(draft !== undefined && { draft }),
      ...(locale && { locale }),
      ...(fallbackLocale && { fallbackLocale }),
      ...(select && { select: select as SelectType }),
    }

    if (data) {
      const virtualFieldNames = getCollectionVirtualFieldNames(payload.config, collectionSlug)
      const inputData = stripVirtualFields(data, virtualFieldNames)
      duplicateOptions.data = transformPointDataToPayload(inputData)
    }

    const result = await payload.duplicate(duplicateOptions)

    logger.info(`Successfully duplicated document in ${collectionSlug} with new ID: ${result.id}`)

    return {
      content: [
        {
          type: 'text',
          text: `Document duplicated successfully in collection "${collectionSlug}"!\nDuplicated document:\n\`\`\`json\n${JSON.stringify(result)}\n\`\`\``,
        },
      ],
      doc: result as Record<string, unknown>,
      structuredContent: result as Record<string, unknown>,
    }
  } catch (error) {
    const errorMessage = error instanceof Error ? error.message : 'Unknown error'
    logger.error(`Error duplicating document in ${collectionSlug}: ${errorMessage}`)
    return formatCollectionError({ action: 'duplicating', collectionSlug, error, req })
  }
})
