const getValidationErrors = (error: unknown): undefined | unknown[] => {
  if (!error || typeof error !== 'object') {
    return undefined
  }

  const data = 'data' in error ? error.data : undefined
  if (!data || typeof data !== 'object' || !('errors' in data) || !Array.isArray(data.errors)) {
