    : ''

  return {
    content: [
      {
        type: 'text',
        text: `Error ${action} document in collection "${collectionSlug}": ${errorMessage}${schemaText}`,
      },
    ],
    isError: true,
    ...(schema
      ? {
          structuredContent: {
            collectionSlug,
            errors,
            schema,
          },
        }
      : {}),
  }
}
